public class MiniBank {
    static abstract class Account {protected final String accountNumber,ownerName;protected long balance;Account(String n,String o,long b){accountNumber=n;ownerName=o;balance=b;}abstract double interestRate();abstract boolean canWithdraw(long amount);public long getBalance(){return balance;}public boolean deposit(long amount){if(amount<=0)return false;balance+=amount;return true;}public boolean withdraw(long amount){if(amount<=0||!canWithdraw(amount))return false;balance-=amount;return true;}public String toString(){return accountNumber+" "+ownerName+" balance="+balance;}}
    static class SavingsAccount extends Account {private final long minBalance;SavingsAccount(String n,String o,long b,long min){super(n,o,b);minBalance=min;}double interestRate(){return 4.0;}boolean canWithdraw(long a){return balance-a>=minBalance;}}
    static class CurrentAccount extends Account {private final long overdraftLimit;CurrentAccount(String n,String o,long b,long limit){super(n,o,b);overdraftLimit=limit;}double interestRate(){return 0.0;}boolean canWithdraw(long a){return balance-a>=-overdraftLimit;}}
    static class FixedDepositAccount extends Account {FixedDepositAccount(String n,String o,long b){super(n,o,b);}double interestRate(){return 7.0;}boolean canWithdraw(long a){return false;}}
    public static void main(String[] args){Account[] accounts={new SavingsAccount("AC0001","Aarav",5000,1000),new CurrentAccount("AC0002","Diya",2000,5000),new FixedDepositAccount("AC0003","Kabir",10000)};for(Account a:accounts)System.out.println(a+" interest="+a.interestRate());}
}
